// Secure version of the application
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config(); // Load environment variables from .env file

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Secure headers
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'SAMEORIGIN');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Referrer-Policy', 'same-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=()');
  res.setHeader('X-Powered-By', 'PHP'); // Mask server information
  next();
});

// Health endpoint with minimal information
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // Removed timestamp to avoid fingerprinting
});

// Users endpoint with no sensitive data
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' }, // Removed email to limit information exposure
    { id: 2, name: 'Bob' },
  ]);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' }); // Generic error message
});

// Start server on configurable port
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

