const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

// Security middleware
app.use(helmet());
app.use(cors({ origin: process.env.ALLOWED_ORIGIN || '*' }));
app.use(morgan('combined'));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint - with configurable test data
app.get('/users', (req, res) => {
  const testUsers = [
    { id: 1, name: 'Alice', email: process.env.TEST_USER_1_EMAIL || 'alice@example.com' },
    { id: 2, name: 'Bob', email: process.env.TEST_USER_2_EMAIL || 'bob@example.com' },
  ];
  res.json(testUsers);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

// Start server with config from environment
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

